int feasible(double r) {
    long long lo[55], hi[55];
    for (int i = 0; i < n; i++) {
        lo[i] = (long long)ceil(a[i] * (1.0 - r));
        if (lo[i] < 1) lo[i] = 1;
        hi[i] = (long long)floor(a[i] * (1.0 + r));
    }
    // Greedy: pick smallest valid b[i]
    long long prev = lo[0]; // smallest in range
    if (prev > hi[0]) return 0;
    for (int i = 1; i < n; i++) {
        // smallest multiple of prev >= lo[i]
        long long k = (lo[i] + prev - 1) / prev;
        long long b = k * prev;
        if (b > hi[i]) return 0;
        prev = b;
    }
    return 1;
}

