#include <math.h>

static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long *a = (long long *)malloc((size_t)n * sizeof(long long));
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);

    qsort(a, n, sizeof(long long), cmp_ll);

    /*
      Let intervals for each coin under ratio r be:
        b_i in [ceil(a_i(1-r)), floor(a_i(1+r))]
      We need existence of integers b_1 <= b_2 <= ... actually stronger:
        b_{i+1} is divisible by b_i
      Since divisibility chain implies b_i = x * k_i with k_i positive integers
      and k_1=1 after choosing x=b_1.

      Feasibility for fixed r:
      DP over possible chosen values from intervals is too large.
      Key observation:
      n is small enough in original problem setting? Since statement omitted constraints,
      we use a practical exact method based on recursive generation of divisibility chains
      bounded by intervals.

      We binary search r and test feasibility by DFS:
      choose b_1 in its interval, then recursively choose multiples in next intervals.

      To keep it efficient, we prune heavily:
      - b_i must lie in interval [L_i, R_i]
      - next values are multiples of current within next interval
      - if some interval empty => infeasible

      This is exact and works well for moderate constraints.
    */

    double lo = 0.0, hi = 1.0;
    for (int i = 0; i < n; ++i) {
        if (a[i] == 0) { hi = 2.0; break; }
    }
    while (1) {
        int ok = 1;
        for (int i = 0; i < n; ++i) {
            double Ld = a[i] * (1.0 - hi);
            double Rd = a[i] * (1.0 + hi);
            long long L = (long long)ceil(Ld - 1e-12);
            long long R = (long long)floor(Rd + 1e-12);
            if (R < 1) ok = 0;
            if (L < 1) L = 1;
            if (L > R) ok = 0;
        }
        if (ok) break;
        hi *= 2.0;
        if (hi > 1e18) break;
    }

    long long *L = (long long *)malloc((size_t)n * sizeof(long long));
    long long *R = (long long *)malloc((size_t)n * sizeof(long long));

    /* DFS feasibility */
    int feasible(double r) {
        for (int i = 0; i < n; ++i) {
            double Ld = a[i] * (1.0 - r);
            double Rd = a[i] * (1.0 + r);
            L[i] = (long long)ceil(Ld - 1e-12);
            R[i] = (long long)floor(Rd + 1e-12);
            if (L[i] < 1) L[i] = 1;
            if (L[i] > R[i]) return 0;
        }

        /* recursive lambda-style via manual stack function */
        int dfs(int idx, long long prev) {
            if (idx == n) return 1;
            long long startk = (L[idx] + prev - 1) / prev;
            long long endk = R[idx] / prev;
            if (startk > endk) return 0;

            /* Try values near original coin first */
            long long targetk = a[idx] / prev;
            if (targetk < startk) targetk = startk;
            if (targetk > endk) targetk = endk;

            long long radius = 0;
            while (targetk - radius >= startk || targetk + radius <= endk) {
                long long candk;

                candk = targetk - radius;
                if (candk >= startk && candk <= endk) {
                    if (dfs(idx + 1, prev * candk)) return 1;
                }
                if (radius != 0) {
                    candk = targetk + radius;
                    if (candk >= startk && candk <= endk) {
                        if (dfs(idx + 1, prev * candk)) return 1;
                    }
                }
                radius++;
                if (radius > endk - startk + 1) break;
            }
            return 0;
        }

        /* Try possible first coin values */
        long long start = L[0], end = R[0];
        long long target = a[0];
        if (target < start) target = start;
        if (target > end) target = end;

        long long radius = 0;
        while (target - radius >= start || target + radius <= end) {
            long long cand;
            cand = target - radius;
            if (cand >= start && cand <= end) {
                if (dfs(1, cand)) return 1;
            }
            if (radius != 0) {
                cand = target + radius;
                if (cand >= start && cand <= end) {
                    if (dfs(1, cand)) return 1;
                }
            }
            radius++;
            if (radius > end - start + 1) break;
        }
        return 0;
    }

    for (int it = 0; it < 70; ++it) {
        double mid = (lo + hi) * 0.5;
        if (feasible(mid)) hi = mid;
        else lo = mid;
    }

    printf("%.12f\n", hi);

    free(L);
    free(R);
    free(a);
    return 0;
}

