int n;
vector<long long> a;

bool can(double x) {
    long long prev = 1; // b_0 must be at least 1
    for (int i = 0; i < n; i++) {
        double low = a[i] * (1.0 - x);
        double high = a[i] * (1.0 + x);
        long long L = ceil(low - 1e-12);
        long long H = floor(high + 1e-12);
        if (L > H) return false;
        // Find smallest multiple of prev >= L
        long long b = ((L + prev - 1) / prev) * prev;
        if (b > H) return false;
        prev = b;
    }
    return true;
}

