// Binary search on answer r
// For given r, check if feasible
// Greedy: for each coin, find range [lo,hi], pick b_i greedily

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<long double> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    sort(a.begin(), a.end());

    auto feasible = [&](long double x) -> bool {
        const long double EPS = 1e-18L;

        long double L0 = ceil((1.0L - x) * a[0] - EPS);
        long double R0 = floor((1.0L + x) * a[0] + EPS);

        long long low = max(1LL, (long long)L0);
        long long high = (long long)R0;
        if (low > high) return false;

        // dp interval of possible current coin values
        long long curL = low, curR = high;

        for (int i = 1; i < n; ++i) {
            long double Li_ld = ceil((1.0L - x) * a[i] - EPS);
            long double Ri_ld = floor((1.0L + x) * a[i] + EPS);

            long long Li = max(1LL, (long long)Li_ld);
            long long Ri = (long long)Ri_ld;
            if (Li > Ri) return false;

            // Need b_i to be a multiple of some previous value v in [curL, curR]
            // So possible b_i are integers y in [Li, Ri] such that exists v in [curL, curR] with v|y.
            // This is equivalent to y belonging to union of multiples of v.
            // We only need resulting possible interval for next step:
            // all y for which floor(y/curR) < ceil(y/curL)? Hard to maintain exactly.
            //
            // Key observation:
            // If some y is feasible, then every y' in [y, floor(y*curR/curL)] is not guaranteed.
            // Exact union may be fragmented.
            //
            // But for decision, greedy with smallest feasible current value works:
            // maintain smallest achievable value. For each step choose smallest b_i in [Li,Ri]
            // divisible by previous chosen. This minimizes future constraints and is optimal.

            long long prev = curL;
            long long k = (Li + prev - 1) / prev;
            long long y = k * prev;
            if (y > Ri) return false;

            curL = curR = y;
        }
        return true;
    };

    long double lo = 0.0L, hi = 1.0L;
    while (!feasible(hi)) hi *= 2.0L;

    for (int it = 0; it < 100; ++it) {
        long double mid = (lo + hi) / 2.0L;
        if (feasible(mid)) hi = mid;
        else lo = mid;
    }

    cout << fixed << setprecision(15) << (double)hi << "\n";
    return 0;
}

