public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        long[] a = new long[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(st.nextToken());
        }
        Arrays.sort(a);

        double lo = 0.0, hi = 1.0;
        while (hi - lo > 1e-12) {
            double mid = (lo + hi) / 2.0;
            if (can(mid, a)) {
                hi = mid;
            } else {
                lo = mid;
            }
        }
        System.out.printf("%.12f\n", hi);
    }

    static boolean can(double ratio, long[] a) {
        int n = a.length;
        long prev = a[0]; // keep first unchanged
        for (int i = 1; i < n; i++) {
            long minVal = (long) Math.ceil(a[i] * (1 - ratio));
            long maxVal = (long) Math.floor(a[i] * (1 + ratio));
            if (minVal > maxVal) return false;

            // Find smallest multiple of prev >= minVal
            long mult = ((minVal + prev - 1) / prev) * prev;
            if (mult > maxVal) return false;
            prev = mult;
        }
        return true;
    }
}

