public class Main {
    static int[] a;
    static int n;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        a = new int[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextInt();

        double lo = 0, hi = 1;
        for (int iter = 0; iter < 100; iter++) {
            double mid = (lo + hi) / 2;
            if (feasible(mid)) hi = mid;
            else lo = mid;
        }
        System.out.printf("%.9f%n", hi);
    }

    static boolean feasible(double r) {
        Set<Long> cur = new HashSet<>();
        long lo0 = (long)Math.ceil(a[0] * (1 - r));
        long hi0 = (long)(a[0] * (1 + r));
        if (lo0 < 1) lo0 = 1;
        for (long v = lo0; v <= hi0; v++) cur.add(v);
        for (int i = 1; i < n; i++) {
            long loI = (long)Math.ceil(a[i] * (1 - r));
            long hiI = (long)(a[i] * (1 + r));
            if (loI < 1) loI = 1;
            Set<Long> next = new HashSet<>();
            for (long b : cur) {
                long start = (loI + b - 1) / b * b;
                for (long v = start; v <= hiI; v += b) next.add(v);
            }
            cur = next;
            if (cur.isEmpty()) return false;
        }
        return !cur.isEmpty();
    }
}

