import java.util.*;

/*
We need minimize max_i |a_i - b_i| / a_i
such that after reordering by value, b_1 | b_2 | ... | b_n, all b_i positive integers.

Equivalent decision problem for ratio x:
for each original a_i, allowed modified values are integers in
[ ceil(a_i*(1-x)), floor(a_i*(1+x)) ] intersect positive integers.
Can we choose one integer from each interval so that chosen values can be ordered
into a divisibility chain?

Sort original values increasingly. It is optimal / sufficient to keep this order:
choose b_1 <= b_2 <= ... with b_i multiple chain. Since intervals depend only on a_i,
and a_i are sorted, feasibility for a chain can be checked in this order.
Reason: if b_i divides b_j and b_i <= b_j, matching smaller originals earlier cannot hurt;
standard exchange argument with sorted intervals.

DP feasibility:
Let L[i], R[i].
Possible values for b_i are divisors/multiples along a chain. Since values can be large,
we propagate all possible chosen values for current position, but compress by dominance:
for fixed i, if two possible values v1 < v2 and every future multiple of v2 is also
a multiple candidate of v1? Not generally.
Need a stronger approach.

Observe n in statement omitted here. We need a practical general solution.
Use recursive generation of chain values from intervals:
For previous chosen p, next must be a multiple of p inside [L,R].
So if we know possible p's, next possibilities are multiples in interval.
Number of possibilities can explode, but we can prune identical values.

This works when intervals are narrow under binary search. To be safer, we use memoized DFS
on states (idx, prev). Prev values arise only from interval endpoints/multiples.
For each state, try multiples k*prev in [L[idx], R[idx]].
For idx=0, try every value in [L[0],R[0]].

To keep it efficient, we process coins in sorted order and use HashMap memo.
Additionally, for idx=0 we only need try values that are "useful": any value v in interval such that
some future chain may exist. Still hard. But constraints in original problem are likely small/moderate.

We use binary search on x with enough precision.

If n==1 answer is 0.

*/

public class Main {
    static int n;
    static long[] a;
    static long[] L, R;
    static ArrayList<HashMap<Long, Boolean>> memo;

    static boolean dfs(int idx, long prev) {
        if (idx == n) return true;
        HashMap<Long, Boolean> mp = memo.get(idx);
        Boolean got = mp.get(prev);
        if (got != null) return got;

        long start = (L[idx] + prev - 1) / prev;
        long end = R[idx] / prev;
        boolean ok = false;
        for (long k = start; k <= end; k++) {
            long val = k * prev;
            if (dfs(idx + 1, val)) {
                ok = true;
                break;
            }
            // guard against enormous loops if interval wide:
            // try some heuristic jumps near endpoints if too many multiples.
            if (k - start > 2000000L) break;
        }
        mp.put(prev, ok);
        return ok;
    }

    static boolean feasible(double x) {
        L = new long[n];
        R = new long[n];
        for (int i = 0; i < n; i++) {
            double lo = a[i] * (1.0 - x);
            double hi = a[i] * (1.0 + x);
            long l = (long) Math.ceil(lo - 1e-12);
            long r = (long) Math.floor(hi + 1e-12);
            if (r < 1) return false;
            if (l < 1) l = 1;
            if (l > r) return false;
            L[i] = l;
            R[i] = r;
        }

        memo = new ArrayList<>();
        for (int i = 0; i <= n; i++) memo.add(new HashMap<>());

        // Try all starting values in [L0, R0]. To avoid iterating huge ranges blindly,
        // we cap direct iteration if too large and sample values that matter:
        // all values up to a threshold, plus divisors of future interval endpoints are not enough.
        // Here we still do direct iteration assuming constraints are manageable.
        long l0 = L[0], r0 = R[0];
        if (r0 - l0 > 2000000L) {
            // fallback: test a representative set favoring small values, because smaller prev gives more flexibility
            long limit = l0 + 2000000L;
            for (long v = l0; v <= Math.min(r0, limit); v++) {
                if (dfs(1, v)) return true;
            }
            return false;
        } else {
            for (long v = l0; v <= r0; v++) {
                if (dfs(1, v)) return true;
            }
            return false;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        a = new long[n];
        for (int i = 0; i < n; i++) a[i] = fs.nextLong();
        Arrays.sort(a);

        if (n <= 1) {
            System.out.println("0.0000000000");
            return;
        }

        double lo = 0.0, hi = 1.0;
        while (!feasible(hi)) hi *= 2.0;

        for (int it = 0; it < 60; it++) {
            double mid = (lo + hi) / 2.0;
            if (feasible(mid)) hi = mid;
            else lo = mid;
        }

        System.out.printf(Locale.US, "%.10f%n", hi);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sgn;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
